class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None
        self.random = None

def cloneTree(root):
    if not root:
        return None

    # Map to store original node -> cloned node
    mapping = {}

    # First pass: create all new nodes without setting pointers
    def create_nodes(node):
        if not node:
            return None
        new_node = Node(node.data)
        mapping[node] = new_node
        create_nodes(node.left)
        create_nodes(node.right)

    # Second pass: set left, right, and random pointers
    def set_pointers(node):
        if not node:
            return
        cloned = mapping[node]
        cloned.left = mapping.get(node.left)
        cloned.right = mapping.get(node.right)
        cloned.random = mapping.get(node.random)
        set_pointers(node.left)
        set_pointers(node.right)

    create_nodes(root)
    set_pointers(root)

    return mapping[root]

