import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        print(0)
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        print(0)
        return

    if n == 0:
        print(0)
        return

    nodes = [None] * (n + 1)
    node_map = {}

    # Create nodes based on data
    for i in range(1, n + 1):
        try:
            data = int(next(iterator))
            node = Node(data)
            nodes[i] = node
            node_map[data] = node
        except StopIteration:
            break

    # Read left children
    for i in range(1, n + 1):
            try:
                left_idx = int(next(iterator))
                if left_idx != -1:
                    nodes[i].left = nodes[left_idx]
            except StopIteration:
                break

    # Read right children
    for i in range(1, n + 1): 
        try:
            right_idx = int(next(iterator))
            if right_idx != -1:
                nodes[i].right = nodes[right_idx]
        except StopIteration:
            break

    # Read random pointers
    for i in range(1, n + 1):
                try:
                    random_idx = int(next(iterator))
                    if random_idx != -1:
                        nodes[i].random = nodes[random_idx]
                except StopIteration:
                    break

    root = nodes[1]
    cloned_root = cloneTree(root)

    # Verify cloning
    def verify(original, cloned):
        if not original and not cloned:
            return True
        if not original or not cloned:
            return False
        if original.data != cloned.data:
            return False
        if not verify(original.left, cloned.left):
            return False
        if not verify(original.right, cloned.right):
            return False
        if not verify(original.random, cloned.random):
            return False
        return True

    if verify(root, cloned_root):
